import os
import sqlite3
from flask import Flask, request, jsonify, render_template_string

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "dev-secret")

DB_PATH = "db.sqlite3"

# HTML template for the forum UI
HTML_TEMPLATE = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MyForum</title>
    <style>
        body { font-family: sans-serif; max-width: 800px; margin: 2rem auto; padding: 0 1rem; }
        .message { border: 1px solid #ddd; padding: 1rem; margin-bottom: 1rem; border-radius: 8px; background: #f9f9f9; }
        .username { font-weight: bold; color: #333; margin-bottom: 0.5rem; }
        .content { color: #555; }
        .form-group { margin-bottom: 1rem; }
        input, textarea, button { width: 100%; padding: 0.5rem; margin-bottom: 0.5rem; box-sizing: border-box; }
        button { background: #28a745; color: white; border: none; cursor: pointer; }
        button:hover { background: #218838; }
        .error { color: red; background: #ffdddd; padding: 0.5rem; margin-bottom: 1rem; border-radius: 4px; }
    </style>
</head>
<body>
    <h1>MyForum</h1>

    <div class="form-group">
        <textarea id="msgContent" rows="3" placeholder="What's on your mind?"></textarea>
        <input type="text" id="msgUsername" placeholder="Your username">
        <button onclick="postMessage()">Post Message</button>
    </div>

    <div id="messages">
        {% for msg in messages %}
        <div class="message">
            <span class="username">{{ msg.username }}:</span>
            <div class="content">{{ msg.content }}</div>
        </div>
        {% endfor %}
    </div>

    <script>
        async function loadMessages() {
            const limit = {{ limit }};
            const offset = {{ offset }};
            const sort = "{{ sort }}";
            const resp = await fetch(`/messages?limit=${limit}&offset=${offset}&sort=${sort}`);
            const data = await resp.text();
            document.getElementById('messages').innerHTML = data;
        }

        async function postMessage() {
            const content = document.getElementById('msgContent').value.trim();
            const username = document.getElementById('msgUsername').value.trim() || "Anonymous";
            if (!content) return;

            const resp = await fetch('/messages', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ content, username })
            });
            const result = await resp.json();
            if (result.status === 'ok') {
                document.getElementById('msgContent').value = '';
                loadMessages();
            } else {
                alert('Failed to post: ' + (result.error || 'Unknown error'));
            }
        }

        // Initial load
        loadMessages();
    </script>
</body>
</html>
"""

def init_db():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS messages (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL,
        content TEXT NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    conn.commit()
    conn.close()

init_db()

@app.route('/messages', methods=['GET'])
def get_messages():
    try:
        limit = int(request.args.get('limit', 10))
        offset = int(request.args.get('offset', 0))
        sort = request.args.get('sort', 'desc').upper()
    except ValueError:
        return jsonify({"error": "Invalid query parameters"}), 400

    if sort not in ('ASC', 'DESC'):
        sort = 'DESC'

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    # Count total
    c.execute("SELECT COUNT(*) FROM messages")
    total = c.fetchone()[0]

    # Fetch messages
    order = "ASC" if sort == "ASC" else "DESC"
    c.execute("SELECT username, content FROM messages ORDER BY created_at ? LIMIT ? OFFSET ?", (order, limit, offset))
    rows = c.fetchall()
    conn.close()

    messages = [{"username": row[0], "content": row[1]} for row in rows]

    # Render HTML fragment
    html = render_template_string(HTML_TEMPLATE, messages=messages, limit=limit, offset=offset, sort=sort)
    return html, 200, {'Content-Type': 'text/html'}

@app.route('/messages', methods=['POST'])
def post_message():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({"error": "Invalid request"}), 400

    content = data.get('content')
    username = data.get('username', 'Anonymous')

    if not isinstance(content, str) or not content.strip():
        return jsonify({"error": "Content is required"}), 400

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("INSERT INTO messages (username, content) VALUES (?, ?)", (username, content))
    conn.commit()
    conn.close()

    return jsonify({"status": "ok"}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
